import React, { useContext, useRef, useState, useEffect } from 'react'
import './Navbar.css'
import logo from '../Assets/logo.png'
import cart_icon from '../Assets/cart_icon.png'
import { Link } from 'react-router-dom'
import { ShopContext } from '../../Context/ShopContext'
import nav_dropdown from '../Assets/nav_dropdown.png'

export const Navbar = () => {
    const [menu, setMenu] = useState("shop");
    const [scrolled, setScrolled] = useState(false);
    const { getTotalCartItems } = useContext(ShopContext);
    const menuRef = useRef();

    useEffect(() => {
        const handleScroll = () => {
            setScrolled(window.scrollY > 50);
        };
        window.addEventListener("scroll", handleScroll);
        return () => window.removeEventListener("scroll", handleScroll);
    }, []);

    const dropdown_toggle = (e) => {
        menuRef.current.classList.toggle('nav-menu-visible');
        e.target.classList.toggle('open');
    }

    return (
        <div className={`navbar ${scrolled ? 'navbar-scrolled' : ''}`}>
            <Link to='/' style={{ textDecoration: 'none' }} className="nav-logo">
                <img src={logo} alt="logo" />
                <p>SHOPPER</p>
            </Link>

            <img className='nav-dropdown' onClick={dropdown_toggle} src={nav_dropdown} alt="menu" />
            
            <ul ref={menuRef} className="nav-menu">
                <li onClick={() => setMenu("shop")} className={menu === "shop" ? "active" : ""}>
                    <Link to='/'>Shop</Link>
                </li>
                <li onClick={() => setMenu("mens")} className={menu === "mens" ? "active" : ""}>
                    <Link to='/mens'>Men</Link>
                </li>
                <li onClick={() => setMenu("womens")} className={menu === "womens" ? "active" : ""}>
                    <Link to='/womens'>Women</Link>
                </li>
                <li onClick={() => setMenu("kids")} className={menu === "kids" ? "active" : ""}>
                    <Link to='/kids'>Kids</Link>
                </li>
            </ul>

            <div className="nav-login-cart">
                {localStorage.getItem('auth-token') 
                    ? <button className="logout-btn" onClick={() => { localStorage.removeItem('auth-token'); window.location.replace("/") }}>Logout</button> 
                    : <Link to='/login'><button className="login-btn">Login</button></Link>
                }
                
                <div className="cart-container">
                    <Link to='/cart'><img src={cart_icon} alt="cart" /></Link>
                    <div className="nav-cart-count">{getTotalCartItems()}</div>
                </div>
            </div>
        </div>
    )
}

export default Navbar;
